import{c as e,Q as t,j as n,m as s}from"./chunks/framework.DOi4mjdC.js";const d=JSON.parse('{"title":"InitValue","description":"","frontmatter":{},"headers":[{"level":1,"title":"InitValue","slug":"initvalue"},{"level":2,"title":"功能说明","slug":"功能说明"},{"level":2,"title":"函数原型","slug":"函数原型"},{"level":2,"title":"参数说明","slug":"参数说明"},{"level":2,"title":"返回值说明","slug":"返回值说明"},{"level":2,"title":"约束说明","slug":"约束说明"},{"level":2,"title":"调用示例","slug":"调用示例"}],"relativePath":"api/Utils-API/原型注册与管理/OpParamDef/InitValue.md","filePath":"api/Utils-API/原型注册与管理/OpParamDef/InitValue.md"}'),l={name:"api/Utils-API/原型注册与管理/OpParamDef/InitValue.md"};function p(i,a,r,u,c,o){return t(),n("div",null,[...a[0]||(a[0]=[s(`<h1 id="initvalue" tabindex="-1">InitValue <a class="header-anchor" href="#initvalue" aria-label="Permalink to &quot;InitValue&quot;">​</a></h1><h2 id="功能说明" tabindex="-1">功能说明 <a class="header-anchor" href="#功能说明" aria-label="Permalink to &quot;功能说明&quot;">​</a></h2><p>通过该host侧接口设置算子输出的初始值，设置后会在算子执行前对算子输出的GM空间进行清零操作或者插入memset类算子进行初始值设置。</p><p><strong>InitValue和接口配合使用，SetNeedAtomic接口需要配置为true。</strong></p><h2 id="函数原型" tabindex="-1">函数原型 <a class="header-anchor" href="#函数原型" aria-label="Permalink to &quot;函数原型&quot;">​</a></h2><ul><li><p>在算子执行前，对输出参数对应GM空间进行清零。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>OpParamDef &amp;InitValue(uint64_t value)</span></span></code></pre></div></li><li><p>指定输出参数初值的类型和值，输出参数调用该接口，会在算子执行前，对输出参数对应GM空间插入对应类型和值的memset类算子。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>OpParamDef &amp;InitValue(const ScalarVar &amp;value)</span></span></code></pre></div></li><li><p>指定输出参数初值类型和值的列表，依次对应输出参数的数据类型和数据格式组合，会在算子执行前，对输出参数对应GM空间插入对应类型和值的memset类算子。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>OpParamDef &amp;InitValue(const std::vector&lt;ScalarVar&gt; &amp;value)</span></span></code></pre></div></li></ul><h2 id="参数说明" tabindex="-1">参数说明 <a class="header-anchor" href="#参数说明" aria-label="Permalink to &quot;参数说明&quot;">​</a></h2><table tabindex="0"><thead><tr><th>参数</th><th>输入/输出</th><th>说明</th></tr></thead><tbody><tr><td>value</td><td>输入</td><td>uint64_t类型参数 仅支持输入0，输出参数调用该接口，会在算子执行前，对输出参数对应GM空间进行清零。 ScalarVar类型参数 ScalarVar用于指定输出参数初值的类型ScalarType和值ScalarNum，具体定义如下： &lt;pre class=&quot;screen&quot; codetype=&quot;Cpp&quot; id=&quot;zh-cn_topic_0000001960169216_screen1644815588715&quot;&gt;enum class ScalarType : uint32_t { UINT64 = 0, INT64 = 1, UINT32 = 2, INT32 = 3, UINT16 = 4, INT16 = 5, UINT8 = 6, INT8 = 7, FLOAT32 = 8, FLOAT16 = 9, INVALID_DTYPE = static_cast&lt;uint32_t&gt;(-1), }; union ScalarNum { uint64_t value_u64; int64_t value_i64; float value_f32; ScalarNum() : value_u64(0) {} explicit ScalarNum(uint64_t value) : value_u64(value) {} explicit ScalarNum(int64_t value) : value_i64(value) {} explicit ScalarNum(float value) : value_f32(value) {} }; struct ScalarVar { ScalarType scalar_type; ScalarNum scalar_num; ScalarVar(); ScalarVar(ScalarType type, uint64_t num); ScalarVar(ScalarType type, int64_t num); ScalarVar(ScalarType type, int num); ScalarVar(ScalarType type, unsigned int num); ScalarVar(ScalarType type, float num); ScalarVar(ScalarType type, double num); bool operator==(const ScalarVar&amp; other) const; };&lt;/pre&gt; ScalarType当前仅支持UINT64/INT64/UINT32/INT32/UINT16/INT16/UINT8/INT8/FLOAT32/FLOAT16; ScalarNum支持uint64_t/int64_t/float类型。 为方便使用，ScalarVar也支持立即数初始化，示例如下： &lt;pre class=&quot;screen&quot; codetype=&quot;Cpp&quot; id=&quot;zh-cn_topic_0000001960169216_screen9280101782212&quot;&gt;InitValue({ScalarType::INT16, 1});&lt;/pre&gt; const std::vector&lt;ScalarVar&gt; &amp;value类型 指定输出参数初值类型和值的列表，依次对应输出参数的数据类型和数据格式组合。</td></tr></tbody></table><h2 id="返回值说明" tabindex="-1">返回值说明 <a class="header-anchor" href="#返回值说明" aria-label="Permalink to &quot;返回值说明&quot;">​</a></h2><p>OpParamDef算子定义，OpParamDef请参考<a href="./OpParamDef.html">OpParamDef</a>。</p><h2 id="约束说明" tabindex="-1">约束说明 <a class="header-anchor" href="#约束说明" aria-label="Permalink to &quot;约束说明&quot;">​</a></h2><ul><li>InitValue和SetNeedAtomic接口配合使用，否则会出现初始化不生效的情况。</li><li>针对OpParamDef &amp;InitValue(uint64_t value)接口，算子输出参数的数据类型支持范围如下：UINT64/INT64/UINT32/INT32/UINT16/INT16/UINT8/INT8/FLOAT32/FLOAT16，超出该范围为未定义行为。</li><li>针对OpParamDef &amp;InitValue(const std::vector&lt;ScalarVar&gt; &amp;value)接口输入value的size需要与输出参数配置的<a href="./DataType.html">DataType</a>或<a href="./DataTypeList.html">DataTypeList</a>接口参数的size一致。同时，相同数据类型需保证设置的类型和值相同，否则将会报错。</li><li>对于同一个输出参数仅支持调用一种接口设置初值，调用多种InitValue接口为未定义行为；多次调用同一种接口以最后一次调用设置的初值为准。</li><li>基于旧版本CANN包（不支持InitValue特性）生成的自定义算子工程，无法兼容InitValue接口。在使用非当前版本CANN包生成的自定义算子工程时，需特别注意兼容性问题。您可以通过查看自定义算子工程下cmake/util/ascendc_impl_build.py中有无output_init_value字段来确认当前工程是否支持该特性，如果未找到该字段，则需要重新生成自定义算子工程以启用InitValue特性。</li></ul><h2 id="调用示例" tabindex="-1">调用示例 <a class="header-anchor" href="#调用示例" aria-label="Permalink to &quot;调用示例&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// OpParamDef &amp;InitValue(uint64_t value)示例</span></span>
<span class="line"><span>this-&gt;Output(&quot;z&quot;)</span></span>
<span class="line"><span>     .ParamType(REQUIRED)</span></span>
<span class="line"><span>     .DataType({ge::DT_FLOAT16, ge::DT_FLOAT, ge::DT_INT32})</span></span>
<span class="line"><span>     .FormatList({ ge::FORMAT_ND})</span></span>
<span class="line"><span>     .InitValue(0);</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// OpParamDef &amp;InitValue(const ScalarVar &amp;value)示例</span></span>
<span class="line"><span>this-&gt;Output(&quot;z&quot;)</span></span>
<span class="line"><span>     .ParamType(REQUIRED)</span></span>
<span class="line"><span>     .DataType({ge::DT_FLOAT16, ge::DT_FLOAT, ge::DT_INT32})</span></span>
<span class="line"><span>     .FormatList({ ge::FORMAT_ND})</span></span>
<span class="line"><span>     .InitValue({ScalarType::INT16, 1});</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// OpParamDef &amp;InitValue(const std::vector&lt;ScalarVar&gt; &amp;value)示例</span></span>
<span class="line"><span>this-&gt;Output(&quot;z&quot;)</span></span>
<span class="line"><span>     .ParamType(REQUIRED)</span></span>
<span class="line"><span>     .DataType({ge::DT_FLOAT16, ge::DT_FLOAT, ge::DT_INT32})</span></span>
<span class="line"><span>     .FormatList({ ge::FORMAT_ND})</span></span>
<span class="line"><span>     .InitValue({{ScalarType::INT16, 1}, {ScalarType::FLOAT32, 3.2}, {ScalarType::INT64, 7}});</span></span>
<span class="line"><span></span></span>
<span class="line"><span>this-&gt;Output(&quot;z&quot;)</span></span>
<span class="line"><span>     .ParamType(REQUIRED)</span></span>
<span class="line"><span>     .DataType({ge::DT_INT32, ge::DT_FLOAT, ge::DT_INT32})  // 第一个和第三个DataType相同</span></span>
<span class="line"><span>     .Format({ge::FORMAT_ND, ge::FORMAT_ND, ge::FORMAT_NHWC})</span></span>
<span class="line"><span>     .InitValue({{ScalarType::INT16, 1}, {ScalarType::FLOAT32, 3.2}, {ScalarType::INT16, 1}}); // InitValue对应的数据类型和数值也需相同</span></span></code></pre></div>`,14)])])}const m=e(l,[["render",p]]);export{d as __pageData,m as default};
